import test from 'node:test';
import assert from 'node:assert/strict';
import { readFile } from 'node:fs/promises';
import { Game } from '../dist/js/engine.js';
import { BattleAI } from '../dist/js/ai.js';
import { ReplayPlayer, FIXED_STEP } from '../dist/js/session.js';

// These are genuine outputs from the archived v4.4 commit, not expectations
// regenerated by the engine under test. Their accepted commands also make the
// captures reproducible with the source commit recorded in each fixture.
const LEGACY_COMMIT = '9b99bdcd0eae0929dbb84711e8d5072d0b6ebd14';
const fixtures = await Promise.all([2, 3, 4].map(async rules => JSON.parse(await readFile(
  new URL(`./fixtures/legacy-v44-rules${rules}.json`, import.meta.url), 'utf8'))));

function applyCommand(game, command) {
  assert.equal(game.state.tick, command.tick);
  let result;
  if (command.type === 'ability') result = game.activateAbility(command.team, command.groupId);
  else {
    assert.equal(game.state.hands[command.team][command.handIndex], command.cardId);
    result = game.playCard(command.team, command.handIndex, command.x, command.y);
    if (command.groupId) assert.equal(result.groupId, command.groupId);
  }
  assert.equal(result.ok, true, result.reason);
}

function continueOldSnapshot(snapshot, record) {
  const input = structuredClone(snapshot);
  const game = Game.fromSnapshot(input);
  assert.deepEqual(input, snapshot, 'restoring must not mutate the imported file');
  assert.equal(game.state.running, false, 'imports resume only after an explicit start');
  assert.equal(game.dataProfile, 'prototype-v4');
  assert.deepEqual(game.commands, record.commands.slice(0, game.commands.length));
  let cursor = game.commands.length;
  game.start();
  while (game.state.tick < record.finalTick) {
    while (cursor < record.commands.length && record.commands[cursor].tick === game.state.tick) {
      applyCommand(game, record.commands[cursor++]);
    }
    assert.equal(game.state.running, true, 'legacy combat must not end prematurely');
    game.update(FIXED_STEP);
  }
  while (cursor < record.commands.length && record.commands[cursor].tick === game.state.tick) {
    applyCommand(game, record.commands[cursor++]);
  }
  assert.equal(cursor, record.commands.length);
  return game;
}

for (const fixture of fixtures) {
  const rules = fixture.replay.config.rulesVersion;
  test(`v4.4 rules ${rules}: recorded battle replays with identical full simulation state`, () => {
    assert.equal(fixture.provenance.commit, LEGACY_COMMIT);
    assert.equal(fixture.provenance.baselinePackageVersion, '4.4.0');
    assert.equal(fixture.replay.config.dataProfile, undefined);
    assert.equal(fixture.replay.finalTick, 6000);
    for (const hash of Object.values(fixture.provenance.sourceHashes)) assert.match(hash, /^[a-f0-9]{64}$/);
    for (const id of ['bomber', 'fireball', 'arrows', 'poison', 'spear_goblins', 'zap']) {
      assert.ok(fixture.coverage.cards.includes(id), `${id} must be exercised in the old engine`);
    }
    assert.ok(fixture.coverage.maxProjectiles > 0 && fixture.coverage.maxPoisonAreas > 0);
    assert.ok(fixture.coverage.stunnedObserved);
    if (rules >= 3) assert.ok(fixture.coverage.guardObserved && fixture.coverage.chargeObserved && fixture.coverage.abilities > 0);
    const player = new ReplayPlayer(fixture.replay);
    while (!player.done) player.step();
    assert.equal(player.game.dataProfile, 'prototype-v4');
    // Deliberately compare all simulation fields, RNG, pending casts, commands,
    // entity shapes and configuration. No status/HP/projectile field is omitted.
    assert.deepEqual(player.game.exportSnapshot(), fixture.expectedSnapshot);
    assert.deepEqual(player.game.exportReplay(), fixture.replay);
  });

  for (const checkpoint of fixture.checkpoints) {
    test(`v4.4 rules ${rules}: continue the old ${checkpoint.label} save without changing combat`, () => {
      if (checkpoint.label === 'pending-poison') {
        assert.ok(checkpoint.snapshot.pendingSpells.some(spell => spell.cardId === 'poison'));
      } else if (checkpoint.label === 'projectile-and-area') {
        assert.ok(checkpoint.snapshot.state.projectiles.length > 0 && checkpoint.snapshot.state.areas.length > 0);
      } else if (checkpoint.label === 'phalanx-charge') {
        assert.ok(checkpoint.snapshot.state.formations.some(group => group.mode === 'charge'));
      }
      const resumed = continueOldSnapshot(checkpoint.snapshot, fixture.replay);
      assert.deepEqual(resumed.exportSnapshot(), fixture.expectedSnapshot);
      assert.deepEqual(resumed.exportReplay(), fixture.replay);
    });
  }
}

test('original format-2 saves and replays without rulesVersion keep the old combat profile', () => {
  const fixture = fixtures[0];
  const snapshot = structuredClone(fixture.checkpoints[0].snapshot);
  const replay = structuredClone(fixture.replay);
  delete snapshot.config.rulesVersion;
  delete replay.config.rulesVersion;
  const resumed = continueOldSnapshot(snapshot, replay);
  assert.equal(resumed.rulesVersion, 2);
  assert.deepEqual(resumed.exportSnapshot(), fixture.expectedSnapshot);
  const player = new ReplayPlayer(replay);
  while (!player.done) player.step();
  assert.equal(player.game.rulesVersion, 2);
  assert.deepEqual(player.game.exportSnapshot(), fixture.expectedSnapshot);
});

const aiFixture = JSON.parse(await readFile(new URL('./fixtures/legacy-v44-ai-rules4.json', import.meta.url), 'utf8'));
for (const resume of [false, true]) {
  test(`v4.4 AI: ${resume ? 'old game and AI save continuation' : 'fresh fixed-seed decisions'} preserves inputs and full state`, () => {
    assert.equal(aiFixture.provenance.commit, LEGACY_COMMIT);
    const game = resume ? Game.fromSnapshot(aiFixture.checkpoint.snapshot).start() : new Game(aiFixture.replay.config).start();
    const ai = resume ? BattleAI.fromSnapshot(game, aiFixture.checkpoint.ai) : new BattleAI(game, aiFixture.aiConfig);
    const inputs = aiFixture.replay.commands.filter(command => command.team === 'player' && command.tick >= game.state.tick);
    let cursor = 0;
    while (game.state.tick < aiFixture.replay.finalTick) {
      while (cursor < inputs.length && inputs[cursor].tick === game.state.tick) applyCommand(game, inputs[cursor++]);
      assert.equal(game.state.running, true);
      ai.update(FIXED_STEP);
      game.update(FIXED_STEP);
    }
    assert.equal(cursor, inputs.length);
    assert.deepEqual(game.exportSnapshot(), aiFixture.expectedSnapshot);
    assert.deepEqual(game.exportReplay(), aiFixture.replay);
    assert.deepEqual(ai.exportSnapshot(), aiFixture.expectedAI);
  });
}
